-- Word lists and geography used by the synthetic data generator.
-- Everything lives in the private `seed` schema and is dropped at the end.
--
-- Synthetic-data safety rules:
--   * SSNs use the 9xx area (never issued as SSNs) with group 00–49 (outside ITIN ranges).
--   * Emails use the reserved example.com / example.net / example.org domains.
--   * Phone numbers use the 555 exchange.

create schema if not exists seed;
revoke all on schema seed from public, anon, authenticated;

drop table if exists seed.lists;
create unlogged table seed.lists (name text primary key, items text[] not null);


drop table if exists seed.geo;
create unlogged table seed.geo (
  idx serial primary key, city text not null, state char(2) not null, zip text not null,
  branch_id smallint, area_codes text[] not null
);
